import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------
// Pass 1: multi-CTA per-row partial reduction.
// Rows are processed in L2-resident groups (see ModelNew.forward): each
// launch covers grid = group_rows * bpr CTAs and the absolute row index is
// row0 + ctaid.x / bpr. Input loads carry an L2::evict_last policy so the
// whole row group's input stays resident in L2 for the normalize launch
// that follows immediately on the same stream, which re-reads it from L2
// instead of DRAM, cutting input re-read traffic. CTAs assigned to a row
// grid-stride across it, keeping concurrent accesses adjacent; per-CTA
// f64 partials are accumulated via red.global.add.f64.
// ---------------------------------------------------------------------------
.visible .entry layernorm_partial(
    .param .u64 in_ptr,
    .param .u64 ws_ptr,
    .param .s32 row_size,
    .param .s32 bpr,
    .param .s32 row0
)
{
    .reg .pred %p<8>;
    .reg .b32 %r<16>;
    .reg .b64 %rd<24>;
    .reg .f32 %f<8>;
    .reg .f64 %fd<16>;
    .shared .align 8 .f64 s_sum[256];
    .shared .align 8 .f64 s_ssq[256];
    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [ws_ptr];
    ld.param.s32 %r1, [row_size];
    ld.param.s32 %r4, [bpr];
    ld.param.s32 %r15, [row0];
    mov.u32 %r2, %tid.x;
    mov.u32 %r3, %ctaid.x;
    // keep this row group's input lines resident in L2 for pass 2
    createpolicy.fractional.L2::evict_last.b64 %rd20, 1.0;
    // local_row = ctaid.x / bpr ; bid = ctaid.x % bpr ; row = row0 + local_row
    div.u32 %r5, %r3, %r4;
    mul.lo.u32 %r6, %r5, %r4;
    sub.u32 %r6, %r3, %r6;
    add.s32 %r5, %r5, %r15;
    // row base pointer
    mul.lo.s32 %r13, %r5, %r1;
    cvt.u64.u32 %rd3, %r13;
    shl.b64 %rd3, %rd3, 2;
    add.s64 %rd4, %rd1, %rd3;
    mov.f64 %fd1, 0d0000000000000000;
    mov.f64 %fd2, 0d0000000000000000;
    shr.u32 %r7, %r1, 2;
    and.b32 %r8, %r1, 3;
    setp.eq.s32 %p4, %r8, 0;
    @%p4 bra VEC_SETUP;
    // scalar fallback: grid-stride across scalar elements
    shl.b32 %r9, %r4, 8;
    shl.b32 %r12, %r6, 8;
    add.s32 %r12, %r12, %r2;
SLOOP:
    setp.lt.s32 %p1, %r12, %r1;
    @!%p1 bra REDUCE;
    cvt.u64.u32 %rd5, %r12;
    shl.b64 %rd5, %rd5, 2;
    add.s64 %rd6, %rd4, %rd5;
    ld.global.L2::cache_hint.f32 %f1, [%rd6], %rd20;
    cvt.f64.f32 %fd3, %f1;
    add.f64 %fd1, %fd1, %fd3;
    fma.rn.f64 %fd2, %fd3, %fd3, %fd2;
    add.s32 %r12, %r12, %r9;
    bra SLOOP;
    // vectorized path: grid-stride across float4 vectors
VEC_SETUP:
    shl.b32 %r9, %r4, 8;
    shl.b32 %r12, %r6, 8;
    add.s32 %r12, %r12, %r2;
VLOOP:
    setp.lt.s32 %p1, %r12, %r7;
    @!%p1 bra VTAIL;
    cvt.u64.u32 %rd5, %r12;
    shl.b64 %rd5, %rd5, 4;
    add.s64 %rd6, %rd4, %rd5;
    ld.global.L2::cache_hint.v4.f32 {%f1, %f2, %f3, %f4}, [%rd6], %rd20;
    cvt.f64.f32 %fd3, %f1;
    add.f64 %fd1, %fd1, %fd3;
    fma.rn.f64 %fd2, %fd3, %fd3, %fd2;
    cvt.f64.f32 %fd3, %f2;
    add.f64 %fd1, %fd1, %fd3;
    fma.rn.f64 %fd2, %fd3, %fd3, %fd2;
    cvt.f64.f32 %fd3, %f3;
    add.f64 %fd1, %fd1, %fd3;
    fma.rn.f64 %fd2, %fd3, %fd3, %fd2;
    cvt.f64.f32 %fd3, %f4;
    add.f64 %fd1, %fd1, %fd3;
    fma.rn.f64 %fd2, %fd3, %fd3, %fd2;
    add.s32 %r12, %r12, %r9;
    bra VLOOP;
VTAIL:
    // last CTA of the row folds in up to 3 tail elements
    add.s32 %r13, %r4, -1;
    setp.eq.u32 %p1, %r6, %r13;
    @!%p1 bra REDUCE;
    setp.eq.u32 %p1, %r2, 0;
    @!%p1 bra REDUCE;
    shl.b32 %r13, %r7, 2;
TLOOP:
    setp.lt.s32 %p1, %r13, %r1;
    @!%p1 bra REDUCE;
    cvt.u64.u32 %rd7, %r13;
    shl.b64 %rd7, %rd7, 2;
    add.s64 %rd8, %rd4, %rd7;
    ld.global.L2::cache_hint.f32 %f1, [%rd8], %rd20;
    cvt.f64.f32 %fd3, %f1;
    add.f64 %fd1, %fd1, %fd3;
    fma.rn.f64 %fd2, %fd3, %fd3, %fd2;
    add.s32 %r13, %r13, 1;
    bra TLOOP;
REDUCE:
    // store per-thread partials to shared memory
    cvt.u64.u32 %rd9, %r2;
    shl.b64 %rd9, %rd9, 3;
    mov.u64 %rd10, s_sum;
    add.s64 %rd10, %rd10, %rd9;
    st.shared.f64 [%rd10], %fd1;
    mov.u64 %rd11, s_ssq;
    add.s64 %rd11, %rd11, %rd9;
    st.shared.f64 [%rd11], %fd2;
    bar.sync 0;
    // tree reduction over 256 partials
    mov.u32 %r14, 128;
RLOOP:
    setp.lt.u32 %p1, %r2, %r14;
    @!%p1 bra RSKIP;
    mul.wide.u32 %rd12, %r14, 8;
    mov.u64 %rd10, s_sum;
    add.s64 %rd10, %rd10, %rd9;
    add.s64 %rd13, %rd10, %rd12;
    ld.shared.f64 %fd5, [%rd10];
    ld.shared.f64 %fd6, [%rd13];
    add.f64 %fd5, %fd5, %fd6;
    st.shared.f64 [%rd10], %fd5;
    mov.u64 %rd11, s_ssq;
    add.s64 %rd11, %rd11, %rd9;
    add.s64 %rd13, %rd11, %rd12;
    ld.shared.f64 %fd7, [%rd11];
    ld.shared.f64 %fd8, [%rd13];
    add.f64 %fd7, %fd7, %fd8;
    st.shared.f64 [%rd11], %fd7;
RSKIP:
    bar.sync 0;
    shr.u32 %r14, %r14, 1;
    setp.gt.u32 %p1, %r14, 0;
    @%p1 bra RLOOP;
    // thread 0 accumulates this CTA's partials into the global workspace
    setp.eq.u32 %p1, %r2, 0;
    @!%p1 bra P1_DONE;
    mov.u64 %rd10, s_sum;
    ld.shared.f64 %fd5, [%rd10];
    mov.u64 %rd11, s_ssq;
    ld.shared.f64 %fd6, [%rd11];
    cvt.u64.u32 %rd14, %r5;
    shl.b64 %rd14, %rd14, 4;
    add.s64 %rd15, %rd2, %rd14;
    red.global.add.f64 [%rd15], %fd5;
    add.s64 %rd16, %rd15, 8;
    red.global.add.f64 [%rd16], %fd6;
P1_DONE:
    ret;
}
// ---------------------------------------------------------------------------
// Pass 2: normalize one L2-resident row group. The preceding partial
// launch on the same stream left this group's input resident in L2
// (evict_last policy), so the input re-read below is served from L2
// instead of DRAM. The linear CTA id is reversed within the group so the
// first CTAs process the rows the partial pass streamed last (the hottest
// lines). Streaming input/output evicts first; affine params stay hot.
// ---------------------------------------------------------------------------
.visible .entry layernorm_normalize(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 ws_ptr,
    .param .s32 row_size,
    .param .s32 bpr,
    .param .f32 eps,
    .param .s32 row0
)
{
    .reg .pred %p<8>;
    .reg .b32 %r<16>;
    .reg .b64 %rd<24>;
    .reg .f32 %f<24>;
    .reg .f64 %fd<16>;
    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u64 %rd3, [w_ptr];
    ld.param.u64 %rd4, [b_ptr];
    ld.param.u64 %rd5, [ws_ptr];
    ld.param.s32 %r1, [row_size];
    ld.param.s32 %r4, [bpr];
    ld.param.f32 %f1, [eps];
    ld.param.s32 %r15, [row0];
    mov.u32 %r2, %tid.x;
    mov.u32 %r3, %ctaid.x;
    // L2 cache policies: streaming input/output evicts first, affine
    // params stay hot.
    createpolicy.fractional.L2::evict_first.b64 %rd22, 1.0;
    createpolicy.fractional.L2::evict_last.b64 %rd23, 1.0;
    // reverse linear CTA id within the group: rev = nctaid.x - 1 - ctaid.x
    mov.u32 %r14, %nctaid.x;
    sub.u32 %r14, %r14, 1;
    sub.u32 %r3, %r14, %r3;
    // local_row = rev / bpr ; bid = rev % bpr ; row = row0 + local_row
    div.u32 %r5, %r3, %r4;
    mul.lo.u32 %r6, %r5, %r4;
    sub.u32 %r6, %r3, %r6;
    add.s32 %r5, %r5, %r15;
    mul.lo.s32 %r13, %r5, %r1;
    cvt.u64.u32 %rd6, %r13;
    shl.b64 %rd6, %rd6, 2;
    add.s64 %rd7, %rd1, %rd6;
    add.s64 %rd8, %rd2, %rd6;
    // load final row statistics and derive mean / rstd in f64
    cvt.u64.u32 %rd9, %r5;
    shl.b64 %rd9, %rd9, 4;
    add.s64 %rd10, %rd5, %rd9;
    ld.global.f64 %fd1, [%rd10];
    add.s64 %rd11, %rd10, 8;
    ld.global.f64 %fd2, [%rd11];
    cvt.rn.f64.s32 %fd3, %r1;
    div.rn.f64 %fd4, %fd1, %fd3;
    div.rn.f64 %fd5, %fd2, %fd3;
    mul.f64 %fd6, %fd4, %fd4;
    sub.f64 %fd7, %fd5, %fd6;
    cvt.f64.f32 %fd8, %f1;
    add.f64 %fd7, %fd7, %fd8;
    sqrt.rn.f64 %fd9, %fd7;
    mov.f64 %fd10, 0d3FF0000000000000;
    div.rn.f64 %fd11, %fd10, %fd9;
    cvt.rn.f32.f64 %f2, %fd4;
    cvt.rn.f32.f64 %f3, %fd11;
    shr.u32 %r7, %r1, 2;
    and.b32 %r8, %r1, 3;
    setp.eq.s32 %p4, %r8, 0;
    @%p4 bra VEC2_SETUP;
    // scalar fallback: grid-stride across scalar elements
    shl.b32 %r9, %r4, 8;
    shl.b32 %r12, %r6, 8;
    add.s32 %r12, %r12, %r2;
SLOOP2:
    setp.lt.s32 %p1, %r12, %r1;
    @!%p1 bra K2_END;
    cvt.u64.u32 %rd12, %r12;
    shl.b64 %rd12, %rd12, 2;
    add.s64 %rd13, %rd7, %rd12;
    ld.global.L2::cache_hint.f32 %f5, [%rd13], %rd22;
    add.s64 %rd14, %rd3, %rd12;
    ld.global.L2::cache_hint.f32 %f6, [%rd14], %rd23;
    add.s64 %rd15, %rd4, %rd12;
    ld.global.L2::cache_hint.f32 %f7, [%rd15], %rd23;
    sub.f32 %f8, %f5, %f2;
    mul.f32 %f8, %f8, %f3;
    fma.rn.f32 %f9, %f8, %f6, %f7;
    add.s64 %rd16, %rd8, %rd12;
    st.global.L2::cache_hint.f32 [%rd16], %f9, %rd22;
    add.s32 %r12, %r12, %r9;
    bra SLOOP2;
VEC2_SETUP:
    // Grid-stride across float4 vectors so concurrently active CTAs
    // access adjacent 4 KB regions of the row.
    shl.b32 %r9, %r4, 8;
    shl.b32 %r12, %r6, 8;
    add.s32 %r12, %r12, %r2;
VLOOP2:
    setp.lt.s32 %p1, %r12, %r7;
    @!%p1 bra VTAIL2;
    cvt.u64.u32 %rd12, %r12;
    shl.b64 %rd12, %rd12, 4;
    add.s64 %rd13, %rd7, %rd12;
    ld.global.L2::cache_hint.v4.f32 {%f5, %f6, %f7, %f8}, [%rd13], %rd22;
    add.s64 %rd14, %rd3, %rd12;
    ld.global.L2::cache_hint.v4.f32 {%f9, %f10, %f11, %f12}, [%rd14], %rd23;
    add.s64 %rd15, %rd4, %rd12;
    ld.global.L2::cache_hint.v4.f32 {%f13, %f14, %f15, %f16}, [%rd15], %rd23;
    sub.f32 %f17, %f5, %f2;
    mul.f32 %f17, %f17, %f3;
    fma.rn.f32 %f17, %f17, %f9, %f13;
    sub.f32 %f18, %f6, %f2;
    mul.f32 %f18, %f18, %f3;
    fma.rn.f32 %f18, %f18, %f10, %f14;
    sub.f32 %f19, %f7, %f2;
    mul.f32 %f19, %f19, %f3;
    fma.rn.f32 %f19, %f19, %f11, %f15;
    sub.f32 %f20, %f8, %f2;
    mul.f32 %f20, %f20, %f3;
    fma.rn.f32 %f20, %f20, %f12, %f16;
    add.s64 %rd16, %rd8, %rd12;
    st.global.L2::cache_hint.v4.f32 [%rd16], {%f17, %f18, %f19, %f20}, %rd22;
    add.s32 %r12, %r12, %r9;
    bra VLOOP2;
VTAIL2:
    add.s32 %r13, %r4, -1;
    setp.eq.u32 %p1, %r6, %r13;
    @!%p1 bra K2_END;
    setp.eq.u32 %p1, %r2, 0;
    @!%p1 bra K2_END;
    shl.b32 %r13, %r7, 2;
TLOOP2:
    setp.lt.s32 %p1, %r13, %r1;
    @!%p1 bra K2_END;
    cvt.u64.u32 %rd17, %r13;
    shl.b64 %rd17, %rd17, 2;
    add.s64 %rd18, %rd7, %rd17;
    ld.global.L2::cache_hint.f32 %f5, [%rd18], %rd22;
    add.s64 %rd19, %rd3, %rd17;
    ld.global.L2::cache_hint.f32 %f6, [%rd19], %rd23;
    add.s64 %rd20, %rd4, %rd17;
    ld.global.L2::cache_hint.f32 %f7, [%rd20], %rd23;
    sub.f32 %f8, %f5, %f2;
    mul.f32 %f8, %f8, %f3;
    fma.rn.f32 %f9, %f8, %f6, %f7;
    add.s64 %rd21, %rd8, %rd17;
    st.global.L2::cache_hint.f32 [%rd21], %f9, %rd22;
    add.s32 %r13, %r13, 1;
    bra TLOOP2;
K2_END:
    ret;
}
"""
_ptx_module = None
def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module
def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    module = _get_ptx_module()
    module.function("layernorm_partial")
    module.function("layernorm_normalize")
class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.ln = nn.LayerNorm(normalized_shape=normalized_shape)
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        row_size = 1
        for d in self.ln.normalized_shape:
            row_size *= d
        rows = x.numel() // row_size
        out = torch.empty(x.shape, dtype=x.dtype, device=x.device)
        workspace = torch.zeros((rows, 2), dtype=torch.float64, device=x.device)
        module = _get_ptx_module()
        stream = torch.cuda.current_stream(x.device)
        # L2-resident row-group pipelining: launch the partial reduction and
        # the normalize pass back-to-back for groups of rows whose combined
        # input+output footprint fits in L2. The normalize pass then re-reads
        # the group's input from L2 instead of DRAM, cutting global memory
        # traffic from ~3x to ~2x the tensor size. Pass 1 marks its input
        # lines evict_last and pass 2 marks the streaming input/output
        # evict_first, so the output writes never displace the resident
        # input lines of the in-flight group.
        row_bytes = row_size * x.element_size()
        group_rows = max(1, (72 * 1024 * 1024) // (2 * row_bytes))
        if group_rows > rows:
            group_rows = rows
        max_useful = max(1, (row_size + 1023) // 1024)
        for row_start in range(0, rows, group_rows):
            group = min(group_rows, rows - row_start)
            blocks_per_row = max(1, (768 + group - 1) // group)
            if blocks_per_row > max_useful:
                blocks_per_row = max_useful
            module.launch(
                "layernorm_partial",
                grid=(group * blocks_per_row, 1, 1),
                block=(256, 1, 1),
                arguments=[x, workspace, i32(row_size), i32(blocks_per_row), i32(row_start)],
                shared_memory=4096,
                stream=stream,
            )
            module.launch(
                "layernorm_normalize",
                grid=(group * blocks_per_row, 1, 1),
                block=(256, 1, 1),
                arguments=[x, out, self.ln.weight, self.ln.bias, workspace, i32(row_size), i32(blocks_per_row), f32(self.ln.eps), i32(row_start)],
                shared_memory=0,
                stream=stream,
            )
        return out

